 const bool role_aware=ev.contains("frame_role_contract_version");eventio::Json roles;
 if(role_aware){require(ev.at("frame_role_contract_version")==1&&ev.at("original_source_frame_roles_preserved")==true&&ev.at("protected_source_exposures_not_fitted")==true,"versioned original frame role contract");roles=eventio::read_json(pin(ev.at("source_frame_role_authority"),base));pin(ev.at("source_frame_role_guard"),base);require(roles.at("schema")=="rinkfit.joint_source_frame_protection.v1"&&roles.at("source_video_sha256")==ev.at("source_video").at("sha256"),"frame role authority belongs to exact source video");}
 else require(!ev.contains("source_frame_role_authority"),"unversioned source frame role authority");
 require(review.at("schema")=="rinkfit.named_print_entity_source_review.v1"&&!review.at("source_model_residual_used").template get<bool>()&&!review.at("source_pixels_changed").template get<bool>(),"actual physical entity review");
 for(const auto&a:cfg.at("source_anchors"))pin(a.at("source"),base);
 const auto&columns=ev.at("columns");for(const auto&v:columns.items())pin(v.value(),base);pin(ev.at("seed_material"),base);
 auto seed_material=eventio::read_array<std::int32_t>(base,ev.at("seed_material"),"<i4");auto seed=eventio::read_array<std::uint32_t>(base,columns.at("seed_index"),"<u4");auto frame=eventio::read_array<std::uint32_t>(base,columns.at("frame_index"),"<u4");auto ordinal=eventio::read_array<std::uint64_t>(base,columns.at("source_ordinal"),"<u8");auto material=eventio::read_array<std::uint32_t>(base,columns.at("material_index"),"<u4");auto uv=eventio::read_array<double>(base,columns.at("uv"),"<f8");auto normal=eventio::read_array<double>(base,columns.at("normal"),"<f8");auto profile=eventio::read_array<double>(base,columns.at("profile"),"<f8");auto fb=eventio::read_array<float>(base,columns.at("flow_fb"),"<f4");
 const auto packet_normal=eventio::read_array<double>(base,p.source_json.at("arrays").at("profile_normal"),"<f8");require(packet_normal.size()==2*p.rows.size(),"complete packet profile normal denominator");
 const std::size_t count=p.rows.size()-old;require(seed.size()==count&&frame.size()==count&&ordinal.size()==count&&material.size()==count&&uv.size()==2*count&&normal.size()==2*count&&profile.size()==5*count&&fb.size()==count&&seed_material.size()==cfg.at("seeds").size()&&count==ev.at("selected_rows"),"complete typed source column denominator");
 std::vector<std::uint8_t>init_status;std::vector<double>init_error;
 if(role_aware||ev.contains("numerical_initialization")){const auto&init=ev.at("numerical_initialization");require(init.at("schema")=="rinkfit.native_print_numerical_seed_status.v1"&&init.at("row_count")==count&&init.at("failed_count")==0&&init.at("source_model_used_only_for_numerical_initialization")==true&&init.at("source_physical_identity_inferred")==false&&init.at("failed_seed_default_not_admitted")==true,"failed numerical seed cannot issue an admitted print row");pin(init.at("initializer"),base);pin(init.at("status"),base);pin(init.at("error_px"),base);init_status=eventio::read_array<std::uint8_t>(base,init.at("status"),"|u1");init_error=eventio::read_array<double>(base,init.at("error_px"),"<f8");require(init_status.size()==count&&init_error.size()==count,"complete numerical seed status denominator");for(std::size_t k=0;k<count;++k)require(init_status[k]==1&&std::isfinite(init_error[k])&&init_error[k]>=0,"failed or nonfinite numerical seed was admitted");}
 std::map<std::string,int>eligible;std::map<int,std::vector<int>>authority;
 for(const auto&e:review.at("eligible_materials")){const int mi=e.at("material_index");const auto label=e.at("label").template get<std::string>();require(mi>=0&&std::size_t(mi)<m.materials.size()&&m.materials.at(mi).label==label&&label.rfind("Ad",0)==0&&e.at("physical_surface")=="board"&&eligible.emplace(label,mi).second,"unique reviewed printed material");authority[mi]=e.at("allowed_paths").template get<std::vector<int>>();}
 for(std::size_t i=0;i<seed_material.size();++i){const auto label=cfg.at("seeds").at(i).at("label").template get<std::string>();const auto it=eligible.find(label);require(seed_material[i]==(it==eligible.end()?-1:it->second),"source seed identity differs from its reviewed printed entity");}
 std::size_t expected_frame=0;
